    item_config['constraints'] = current_config.constraints || {};

    // Handle Options
    item_config['options'] = [];
    if (options != null) {
        item_config['options'] = Object.keys(options);

        for (const opt_key in options) {
            option_prices[opt_key] = options[opt_key].price;
